import{d as g,C as t,o as h,c as m,j as e,a as i,E as a,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·里仁","description":"《论语》第 4 篇「里仁」——二十六章原文与导读。里仁为美、君子去仁恶乎成名、一以贯之的忠恕，与见贤思齐。","frontmatter":{"title":"论语·里仁","description":"《论语》第 4 篇「里仁」——二十六章原文与导读。里仁为美、君子去仁恶乎成名、一以贯之的忠恕，与见贤思齐。","category":"guide","aliases":["里仁","里仁篇","里仁第四","论语里仁","lunyu 里仁"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-04.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-04.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/lunyu/chapter-04.md"},x=g({...u,setup(y){const s=[{id:"yi",label:"一、里仁为美",showLabel:!0,sentences:[["子曰：“",{text:"里仁为美",glossary:"lirenweimei"},"，择不处仁，焉得",{text:"知",glossary:"zhi-zhi"},"？”"]],note:"「里仁为美」——居处在有仁风的地方才好（里＝居处，一说「以仁为里」）；「择不处仁，焉得知（智）」——选择居处而不处仁，怎么算明智？此章言环境与抉择之重。"},{id:"er",label:"二、仁者安仁，知者利仁",showLabel:!0,sentences:[["子曰：“不仁者不可以久处",{text:"约",glossary:"yue-yue"},"，不可以长处乐。仁者",{text:"安仁",glossary:"anren"},"，知者",{text:"利仁",glossary:"liren"},"。”"]],note:"「不仁者不可以久处约，不可以长处乐」——不仁的人，既不能久处穷困（约＝穷），也不能长处安乐。盖久困则滥、久乐则淫。「仁者安仁，知者利仁」——仁者安于仁（自然而然），智者利仁（知其有益而行之）。"},{id:"san",label:"三、唯仁者能好人",showLabel:!0,sentences:[["子曰：“唯仁者能好",{text:"人",glossary:"ren-person"},"，能恶人。”"]],note:"「唯仁者能好人，能恶人」——只有仁者才能真正喜爱人、真正憎恶人。因其好恶出于公心，不杂私意。"},{id:"si",label:"四、苟志于仁矣",showLabel:!0,sentences:[["子曰：“苟",{text:"志于仁",glossary:"zhiyuren"},"矣，无恶也。”"]],note:"「苟志于仁矣，无恶也」——真能立志于仁，就不会去做恶事。"},{id:"wu",label:"五、君子无终食之间违仁",showLabel:!0,sentences:[["子曰：“富与贵，是人之所欲也；不以其道得之，不处也。贫与贱，是人之所恶也；不以其道得之，不去也。君子去仁，恶乎成名？君子无",{text:"终食之间",glossary:"zhongshizhijian"},"违仁，",{text:"造次",glossary:"zaoci"},"必于是，",{text:"颠沛",glossary:"dianpei"},"必于是。”"]],note:"「富与贵，是人之所欲也；不以其道得之，不处也」——富贵人人想要，但不合正道得来的，不居（处＝安处）。「贫与贱，是人之所恶也；不以其道得之，不去也」——贫贱人人厌恶，但不合正道摆脱它，也不去。「君子去仁，恶乎成名」——君子若离开仁，凭什么成名？「君子无终食之间违仁，造次必于是，颠沛必于是」——即便一顿饭的工夫也不违仁，仓促时如此，颠沛流离时亦如此。"},{id:"liu",label:"六、我未见力不足者",showLabel:!0,sentences:[["子曰：“我未见好仁者，恶不仁者。好仁者，无以",{text:"尚",glossary:"shang"},"之；恶不仁者，其为仁矣，不使不仁者加乎其身。有能一日用其力于仁矣乎？我未见力不足者。盖有之矣，我未之见也。”"]],note:"「我未见好仁者，恶不仁者」——我没见过真好仁的人、真恶不仁的人。「好仁者，无以尚之」——好仁者，好到无可再上；「恶不仁者，其为仁矣，不使不仁者加乎其身」——恶不仁者之为仁，在于不让不仁之事加到自己身上。「有能一日用其力于仁矣乎？我未见力不足者」——有谁肯把一天的力气用在仁上？我没见过力气不够的。「盖有之矣，我未之见也」——大概有吧，只是我没见过。"},{id:"qi",label:"七、观过，斯知仁矣",showLabel:!0,sentences:[["子曰：“人之过也，各于其",{text:"党",glossary:"dang"},"。观过，斯知仁矣。”"]],note:"「人之过也，各于其党」——人的过错，各随其类而见（党＝类）。「观过，斯知仁矣」——看他犯的是哪一类过错，便可知他仁与不仁（一说「仁」当作「人」）。此章为观人之法。"},{id:"ba",label:"八、朝闻道，夕死可矣",showLabel:!0,sentences:[["子曰：“朝闻道，夕死可矣。”"]],note:"「朝闻道，夕死可矣」——早晨悟得道，当晚死去也可以了。极言道之可贵，非谓轻生。"},{id:"jiu",label:"九、耻恶衣恶食者",showLabel:!0,sentences:[["子曰：“士志于道，而耻恶衣恶食者，未足与议也。”"]],note:"「士志于道，而耻恶衣恶食者，未足与议也」——士人立志求道，却以衣着粗劣、饮食粗淡为耻，那就不值得与他论道了。"},{id:"shi",label:"十、义之与比",showLabel:!0,sentences:[["子曰：“君子之于天下也，无",{text:"适",glossary:"di"},"也，无",{text:"莫",glossary:"mo"},"也，",{text:"义之与比",glossary:"yizhiyubi"},"。”"]],note:"「君子之于天下也，无适也，无莫也，义之与比」——君子对天下事，不刻意亲厚（适＝亲厚），也不刻意疏薄（莫＝疏淡），唯以「义」为依归（比＝依附）。此章言无所偏执而唯义是从。"},{id:"shiyi",label:"十一、君子怀德",showLabel:!0,sentences:[["子曰：“君子怀德，小人怀土；君子怀",{text:"刑",glossary:"xing"},"，小人怀惠。”"]],note:"「君子怀德，小人怀土；君子怀刑，小人怀惠」——君子念念在德，小人念念在乡土田宅；君子念念在法度（刑），小人念念在恩惠。四句以「怀」字两两对举。"},{id:"shier",label:"十二、放于利而行",showLabel:!0,sentences:[["子曰：“",{text:"放于利而行",glossary:"fangyuli"},"，多怨。”"]],note:"「放于利而行，多怨」——凡事依利而行（放＝依循），便多招怨。"},{id:"shisan",label:"十三、以礼让为国",showLabel:!0,sentences:[["子曰：“能以礼让为国乎？何有？不能以礼让为国，如礼何？”"]],note:"「能以礼让为国乎？何有」——能以礼让治国吗？那有何难（何有＝何难之有）。「不能以礼让为国，如礼何」——若不能以礼让治国，礼又有什么用？"},{id:"shisi",label:"十四、不患无位",showLabel:!0,sentences:[["子曰：“不患无位，患所以立；不患莫己知，求为可知也。”"]],note:"「不患无位，患所以立」——不忧没有职位，只忧拿什么立得住；「不患莫己知，求为可知也」——不忧别人不知道自己，只求自己有什么值得被人知道。"},{id:"shiwu",label:"十五、一以贯之",showLabel:!0,sentences:[["子曰：“参乎！吾道一以贯之。”曾子曰：“唯。”子出，门人问曰：“何谓也？”曾子曰：“夫子之道，",{text:"忠恕",glossary:"zhongshu"},"而已矣。”"]],note:"孔子说：「参乎！吾道一以贯之」——曾参啊！我的道是一贯的。曾子应「唯」（是）。孔子出去后，门人问「何谓也」，曾子答：「夫子之道，忠恕而已矣」——夫子的道，就是忠恕罢了。此为《论语》中著名的「一以贯之」章。"},{id:"shiliu",label:"十六、喻于义，喻于利",showLabel:!0,sentences:[["子曰：“君子",{text:"喻",glossary:"yu"},"于义，小人喻于利。”"]],note:"「君子喻于义，小人喻于利」——君子所明白的是义，小人所明白的是利（喻＝明白、通晓）。"},{id:"shiqi",label:"十七、见贤思齐",showLabel:!0,sentences:[["子曰：“",{text:"见贤思齐",glossary:"jianxiansiqi"},"焉，见不贤而内自省也。”"]],note:"「见贤思齐焉，见不贤而内自省也」——见贤人便想与之看齐，见不贤者便向内反省自己是否也有同样的毛病。"},{id:"shiba",label:"十八、事父母几谏",showLabel:!0,sentences:[["子曰：“事父母",{text:"几谏",glossary:"jijian"},"，见志不从，又敬不违，劳而不怨。”"]],note:"「事父母几谏」——事奉父母，要委婉地劝谏（几＝微、婉转）；「见志不从，又敬不违，劳而不怨」——自己的意见不被听从，仍恭敬而不违逆（一说「不违」谓不敢违其几谏之志），虽劳苦而不怨。"},{id:"shijiu",label:"十九、游必有方",showLabel:!0,sentences:[["子曰：“父母在，不远游，游必有方。”"]],note:"「父母在，不远游，游必有方」——父母健在，不出远门；若不得已而游，必有一定之方向（方＝处所、去向），使父母知其所在。"},{id:"ershi",label:"二十、三年无改于父之道",showLabel:!0,sentences:[["子曰：“三年无改于父之道，可谓孝矣。”"]],note:"「三年无改于父之道，可谓孝矣」——三年不改变父亲的做法，便可称孝了。（此章与《学而》第十一章同）"},{id:"ershiyi",label:"二十一、父母之年",showLabel:!0,sentences:[["子曰：“父母之年，不可不知也。一则以喜，一则以惧。”"]],note:"「父母之年，不可不知也」——父母的年纪，不可以不记着。「一则以喜，一则以惧」——一方面因其高寿而喜，一方面因其年迈而惧。"},{id:"ershier",label:"二十二、耻躬之不逮",showLabel:!0,sentences:[["子曰：“古者言之不出，耻",{text:"躬",glossary:"gong-shen"},"之不",{text:"逮",glossary:"dai-ji"},"也。”"]],note:"「古者言之不出，耻躬之不逮也」——古人不轻易把话说出口，是怕自己的行动跟不上（躬＝亲身；逮＝及）。"},{id:"ershisan",label:"二十三、以约失之者鲜矣",showLabel:!0,sentences:[["子曰：“以约失之者鲜矣。”"]],note:"「以约失之者鲜矣」——因能约束自己（约＝检束、简约）而致失误的，很少。"},{id:"ershisi",label:"二十四、讷于言而敏于行",showLabel:!0,sentences:[["子曰：“君子欲",{text:"讷",glossary:"ne"},"于言而敏于行。”"]],note:"「君子欲讷于言而敏于行」——君子要言语迟钝（讷＝说话迟钝，此指不轻易说）而行动敏捷。"},{id:"ershiwu",label:"二十五、德不孤",showLabel:!0,sentences:[["子曰：“德不孤，必有邻。”"]],note:"「德不孤，必有邻」——有德者不会孤单，必有同道来亲近。"},{id:"ershiliu",label:"二十六、事君数，斯辱矣",showLabel:!0,sentences:[["子游曰：“事君",{text:"数",glossary:"shuo"},"，斯辱矣；朋友数，斯疏矣。”"]],note:"子游说：「事君数，斯辱矣；朋友数，斯疏矣」——事奉君主而烦数（数＝屡次、频繁）进谏，就会招致羞辱；对朋友烦数进谏，就会被疏远。言进谏当有节。"}],r=[{id:"lirenweimei",term:"里仁为美",pinyin:"lǐ rén wéi měi",meaning:"居住在有仁厚风气的地方才好。里：动词，居住（一说名词，乡里）。"},{id:"zhi-zhi",term:"知",pinyin:"zhì",meaning:"同「智」。择不处仁，焉得知：选择不居于仁厚之处，怎么算明智呢？"},{id:"yue-yue",term:"约",pinyin:"yuē",meaning:"穷困、俭约（此处指处境困窘）。不仁者不能长久安于穷困。"},{id:"anren",term:"安仁",pinyin:"ān rén",meaning:"以仁为安。仁者自然地安住在仁里，不须勉强。"},{id:"liren",term:"利仁",pinyin:"lì rén",meaning:"以仁为利。智者知道仁对自己有好处，因而行仁。二者境界有别。"},{id:"ren-person",term:"人",pinyin:"rén",meaning:"此处指他人。唯仁者能好人，能恶人：只有仁者才能公正地喜爱人、厌恶人——因其无私，好恶才不失当。"},{id:"zhiyuren",term:"志于仁",pinyin:"zhì yú rén",meaning:"立志于仁。苟志于仁矣，无恶也：真的立志行仁，就不会去做坏事。"},{id:"zhongshizhijian",term:"终食之间",pinyin:"zhōng shí zhī jiān",meaning:"吃一顿饭的时间。喻极短的时间。"},{id:"zaoci",term:"造次",pinyin:"zào cì",meaning:"仓促、匆忙急迫之时。"},{id:"dianpei",term:"颠沛",pinyin:"diān pèi",meaning:"困顿、流离失所。造次必于是，颠沛必于是：无论多急多难，都不离开仁。"},{id:"shang",term:"尚",pinyin:"shàng",meaning:"超过。无以尚之：没有比这更好的了。"},{id:"dang",term:"党",pinyin:"dǎng",meaning:"类别、群类。各于其党：人的过错，各依他所属的那一类。一说「党」指偏私——过错多从偏私处来。"},{id:"di",term:"适",pinyin:"dí",meaning:"专主、一定如此（一说「敌」，敌对）。无适无莫：不刻意要怎样，也不刻意不要怎样。"},{id:"mo",term:"莫",pinyin:"mò",meaning:"不可、不要。与「适」相对。"},{id:"yizhiyubi",term:"义之与比",pinyin:"yì zhī yǔ bǐ",meaning:"只与义相亲比。比：靠拢、依从。合于义便可，不必定于一格。"},{id:"xing",term:"刑",pinyin:"xíng",meaning:"法度、刑典。君子怀刑：君子心里装着法度，知道什么当畏。"},{id:"fangyuli",term:"放于利而行",pinyin:"fǎng yú lì ér xíng",meaning:"一切依利益而行。放：同「仿」，依照。"},{id:"zhongshu",term:"忠恕",pinyin:"zhōng shù",meaning:"忠：尽己；恕：推己及人（己所不欲，勿施于人）。曾子以此二字总括孔子之道。"},{id:"yu",term:"喻",pinyin:"yù",meaning:"明白、懂得。君子喻于义：君子明白的是义。"},{id:"jianxiansiqi",term:"见贤思齐",pinyin:"jiàn xián sī qí",meaning:"见到贤者，就想向他看齐。齐：看齐、赶上。"},{id:"jijian",term:"几谏",pinyin:"jī jiàn",meaning:"委婉地劝谏。几：微、婉转。见志不从，又敬不违：父母不听，仍然恭敬而不违逆。"},{id:"gong-shen",term:"躬",pinyin:"gōng",meaning:"自身、亲身。"},{id:"dai-ji",term:"逮",pinyin:"dài",meaning:"及、赶上。耻躬之不逮：以自己做不到（说的）为耻。"},{id:"ne",term:"讷",pinyin:"nè",meaning:"言语迟钝，指说话谨慎不多。"},{id:"shuo",term:"数",pinyin:"shuò",meaning:"屡次、频繁（此处指频繁地劝谏、絮叨）。事君数，斯辱矣：对君主劝谏太频繁，就会招致羞辱。"}];return(p,n)=>{const l=t("DaoTextReading"),o=t("DaoKeywordCards");return h(),m("div",null,[n[0]||(n[0]=e("h1",{id:"论语·里仁",tabindex:"-1"},[i("论语·里仁 "),e("a",{class:"header-anchor",href:"#论语·里仁","aria-label":'Permalink to "论语·里仁"'},"​")],-1)),n[1]||(n[1]=e("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),e("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=e("p",null,[i("《里仁》是《论语》里"),e("strong",null,"最集中讲「仁」的一篇"),i("——不是定义仁，而是从各个侧面形容它：仁者是安在仁里的，仁者可以久处穷困、久处安乐，仁者能在急难颠沛中也不离开仁。")],-1)),n[3]||(n[3]=e("p",null,"这一篇也有几处是《论语》中最重的句子：「朝闻道，夕死可矣」「君子喻于义，小人喻于利」「见贤思齐焉，见不贤而内自省也」，以及曾子用「忠恕」二字总括孔子之道的第十五章——「夫子之道，忠恕而已矣」。",-1)),n[4]||(n[4]=e("p",null,"还有一段讲孝：几谏、不远游、父母之年一则以喜一则以惧。这一篇的孝，比《为政》更细，也更近人情。",-1)),n[5]||(n[5]=e("p",null,"默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),a(l,{colophon:"里仁第四 · 二十六章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·里仁 原文"}),n[6]||(n[6]=e("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),e("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(o,{items:[{term:"里仁为美",pinyin:["lǐ","rén","wéi","měi"],meaning:"居住在有仁厚风气的地方才好。里：动词，居住（一说名词，乡里）。"},{term:"知",pinyin:["zhì"],meaning:"同「智」。择不处仁，焉得知：选择不居于仁厚之处，怎么算明智呢？"},{term:"约",pinyin:["yuē"],meaning:"穷困、俭约（此处指处境困窘）。不仁者不能长久安于穷困。"},{term:"安仁",pinyin:["ān","rén"],meaning:"以仁为安。仁者自然地安住在仁里，不须勉强。"},{term:"利仁",pinyin:["lì","rén"],meaning:"以仁为利。智者知道仁对自己有好处，因而行仁。二者境界有别。"},{term:"人",pinyin:["rén"],meaning:"此处指他人。唯仁者能好人，能恶人：只有仁者才能公正地喜爱人、厌恶人——因其无私，好恶才不失当。"},{term:"志于仁",pinyin:["zhì","yú","rén"],meaning:"立志于仁。苟志于仁矣，无恶也：真的立志行仁，就不会去做坏事。"},{term:"终食之间",pinyin:["zhōng","shí","zhī","jiān"],meaning:"吃一顿饭的时间。喻极短的时间。"},{term:"造次",pinyin:["zào","cì"],meaning:"仓促、匆忙急迫之时。"},{term:"颠沛",pinyin:["diān","pèi"],meaning:"困顿、流离失所。造次必于是，颠沛必于是：无论多急多难，都不离开仁。"},{term:"尚",pinyin:["shàng"],meaning:"超过。无以尚之：没有比这更好的了。"},{term:"党",pinyin:["dǎng"],meaning:"类别、群类。各于其党：人的过错，各依他所属的那一类。一说「党」指偏私——过错多从偏私处来。"},{term:"适",pinyin:["dí"],meaning:"专主、一定如此（一说「敌」，敌对）。无适无莫：不刻意要怎样，也不刻意不要怎样。"},{term:"莫",pinyin:["mò"],meaning:"不可、不要。与「适」相对。"},{term:"义之与比",pinyin:["yì","zhī","yǔ","bǐ"],meaning:"只与义相亲比。比：靠拢、依从。合于义便可，不必定于一格。"},{term:"刑",pinyin:["xíng"],meaning:"法度、刑典。君子怀刑：君子心里装着法度，知道什么当畏。"},{term:"放于利而行",pinyin:["fǎng","yú","lì","ér","xíng"],meaning:"一切依利益而行。放：同「仿」，依照。"},{term:"忠恕",pinyin:["zhōng","shù"],meaning:"忠：尽己；恕：推己及人（己所不欲，勿施于人）。曾子以此二字总括孔子之道。"},{term:"喻",pinyin:["yù"],meaning:"明白、懂得。君子喻于义：君子明白的是义。"},{term:"见贤思齐",pinyin:["jiàn","xián","sī","qí"],meaning:"见到贤者，就想向他看齐。齐：看齐、赶上。"},{term:"几谏",pinyin:["jī","jiàn"],meaning:"委婉地劝谏。几：微、婉转。见志不从，又敬不违：父母不听，仍然恭敬而不违逆。"},{term:"躬",pinyin:["gōng"],meaning:"自身、亲身。"},{term:"逮",pinyin:["dài"],meaning:"及、赶上。耻躬之不逮：以自己做不到（说的）为耻。"},{term:"讷",pinyin:["nè"],meaning:"言语迟钝，指说话谨慎不多。"},{term:"数",pinyin:["shuò"],meaning:"屡次、频繁（此处指频繁地劝谏、絮叨）。事君数，斯辱矣：对君主劝谏太频繁，就会招致羞辱。"}]}),n[7]||(n[7]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《里仁》二十六章，通篇讲<strong>仁</strong>，却没有给仁下定义。孔子用的是另一种办法——<strong>从各个侧面描画它</strong>：仁者安仁，智者利仁；不仁者不能久处约、长处乐；仁者的好恶公正；仁者无终食之间违仁。</p><p>这一篇还有一条隐含的结构：<strong>仁不是一个高不可攀的目标，而是一个日常的所在</strong>。「里仁为美」起首，讲的是安身之处；「造次必于是，颠沛必于是」讲的是颠簸之中的持守；「君子无终食之间违仁」讲的是吃饭的工夫里也不离。到了末章「德不孤，必有邻」，又落回人与人的关系上。</p><p>中间散落着几句极重的话：朝闻道夕死可矣、君子喻于义、见贤思齐、一以贯之。它们不是论证，是<strong>立标</strong>——把线划在高处，人自会往上够。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「仁」讲成一种安顿，而不是一种规范</strong>：「仁者安仁」——仁者住在仁里，像住在自己家里一样自在。这跟「遵守规范」是两回事：<strong>前者是归宿，后者是约束。</strong> 一个人真正修到某一步，行仁不需要理由。</li><li><strong>它把「富贵贫贱」看得很平静</strong>：「富与贵，是人之所欲也；不以其道得之，不处也」——<strong>欲望不是问题，取舍才是问题。</strong> 这一句连着下文「君子无终食之间违仁」，把「守不守得住」落到了每一顿饭上。</li><li><strong>它用一句话概括了儒家的方法</strong>：曾子说孔子之道「忠恕而已矣」。忠是尽己，恕是推己——<strong>对自己尽力，对别人换位</strong>。两个字，把「仁」变成了可以每天做的事。</li><li><strong>它提供了「如何待人」的两种高阶心法</strong>：「唯仁者能好人，能恶人」——<strong>能公正地厌恶，也是仁</strong>（无私才能当好恶）；「见贤思齐，见不贤而内自省」——<strong>把别人的好坏都变成自己的镜子</strong>。</li><li><strong>它讲清了「说」与「做」的分量</strong>：讷于言而敏于行、耻躬之不逮、以约失之者鲜矣——这一篇反复说的，都是<strong>把话收紧、把事做实</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>先看自己选在什么样的环境里</strong>：「里仁为美」——你的圈子、你常待的地方、你每天看的内容，是不是「仁厚之地」？<strong>环境是一种长期作用力，比意志更持久。</strong></li><li><strong>用「忠恕」二字做待人做事的总原则</strong>：接一件事，先问「我尽力了吗」（忠）；与人相处，先问「换作是我会怎样」（恕）。两问都不难的，难的是<strong>每次都问</strong>。</li><li><strong>别把「见贤思齐」做成攀比</strong>：思齐是往上够，攀比是横向比。<strong>看别人的好处想着学，看别人的不好想着省</strong>，这两件事做顺了，人际关系会轻很多。</li><li><strong>对父母的三条日常功课</strong>：几谏（不硬顶）、游必有方（不让家里悬心）、知父母之年（记得他们老了）。这三条比送礼实在。</li><li><strong>把「利」和「义」的位置摆对</strong>：「君子喻于义，小人喻于利」，不是说不能谈利，而是<strong>遇到两头冲突时，先看义在哪</strong>。顺序比取舍更难拿捏。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《里仁》讲一个很难讲的东西：仁。孔子没有定义它，只是一遍遍指着它说——看，仁者是这样活的。</p><p>他说的几件事，今天听起来都很朴素：欲望可以有，但取之要有道；穷困和安乐都能安住；犯的错落在什么地方，就能看出这个人的底色；见到比自己强的人别嫉妒，想着赶上；见到不怎么样的人别嫌弃，回头照照自己。</p><p>全篇最有分量的是第十五章。孔子说「吾道一以贯之」，曾子听了只答一个「唯」，等人问起才解释：老师的一贯之道，就是<strong>忠恕</strong>。</p><p>——尽自己的心，推自己的心及人。两个字，孔子的道就在这里面了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「仁者安仁，知者利仁」——我做事情，是靠「心安」还是靠「划算」？哪一种能撑得久？</li><li>「君子无终食之间违仁，造次必于是，颠沛必于是」——我上一次在急迫或狼狈时，有没有松开过底线？</li><li>「忠恕」二字，如果拿它检验我这一周，有哪件事没做到「忠」（没尽己）？有哪件事没做到「恕」（没换位）？</li><li>「见贤思齐，见不贤而内自省」——我看到身边人的长处时，第一反应是欣赏还是防卫？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-03">论语·八佾</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-05">论语·公冶长</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',21))])}}});export{c as __pageData,x as default};
